			});
		});

		it('should fail to verify invitation with invalid email', (done) => {
			User.verifyInvitation({ token: 'test', email: 'doesnotexist@test.com' }, (err) => {
				assert.strictEqual(err.message, '[[register:invite.error-invalid-data]]');
